"BEGIN {FS=OFS="\t"}
{
  n++
  gene[n]=$1
  lfc_text[n]=$3
  p_text[n]=$6
  p[n]=$6+0
  ord[n]=n
}
END {
  for (i=2; i<=n; i++) {
    key=ord[i]
    j=i-1
    while (j>=1 && (p[ord[j]] > p[key] || (p[ord[j]] == p[key] && ord[j] > key))) {
      ord[j+1]=ord[j]
      j--
    }
    ord[j+1]=key
  }
  prev=1
  for (rank=n; rank>=1; rank--) {
    k=ord[rank]
    q=p[k]*n/rank
    if (q>1) q=1
    if (q>prev) q=prev
    prev=q
    fdr[k]=q
  }
  print "gene","log2_fold_change","p_value","fdr"
  for (i=1; i<=n; i++) printf "%s\t%s\t%s\t%.17g\n", gene[i],lfc_text[i],p_text[i],fdr[i]
}"
